// Boundary defense in one handler: normalize -> allowlist -> encode.
const express = require("express")
const app = express()

app.post("/api/profile", async (req, res) => {
  // 1) Normalize: the string we validate must be the string we use.
  const username = String(req.body.username ?? "").trim().toLowerCase()

  // 2) Allowlist: what IS valid, nothing else.
  if (!/^[a-z0-9_]{3,20}$/.test(username)) {
    audit.log("validation.reject", { field: "username", endpoint: "/api/profile" })
    return res.status(400).json({ error: "invalid username" })
  }

  // 3) Structured fields: schema, not hand-rolled checks.
  const parsed = profileSchema.safeParse(req.body)
  if (!parsed.success) return res.status(400).json({ error: "invalid body" })

  await db.profiles.upsert({ username, data: parsed.data })

  // 4) Output encoding happens where the data is RENDERED, not here.
  //    (framework interpolation or context-specific escaping)
  res.status(204).end()
})

